SELECT DISTINCT parent.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary parent LEFT JOIN molecule_hierarchy mh ON mh.parent_molregno = parent.molregno LEFT JOIN molecule_dictionary child ON child.molregno = mh.molregno JOIN molecule_dictionary m ON (m.molregno = parent.molregno OR m.molregno = child.molregno) JOIN compound_records cr ON cr.molregno = m.molregno JOIN docs d ON d.doc_id = cr.doc_id JOIN activities act ON act.record_id = cr.record_id JOIN assays a ON a.assay_id = act.assay_id JOIN target_dictionary td ON td.tid = a.tid JOIN compound_structures cs ON cs.molregno = m.molregno WHERE parent.chembl_id = 'CHEMBL376359' AND td.chembl_id = 'CHEMBL284' AND act.standard_type = 'IC50' AND act.standard_units = 'nM' ORDER BY compound_chembl_id, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, target_chembl_id, target_name, target_organism
